#!/usr/bin/env bash
# Run every L0 Catapult configuration sequentially and collect the outputs.
#
#   hls/l0/tcl/run_all.sh [block-regex] [lib-regex] [cfg-regex]
#
# For each block x lib x cfg: hls/l0/tcl/run_cfg.sh, then copy the netlist and
# the reports to hls/l0/out/<top>/ (committed):
#   concat_rtl.v   Catapult concat netlist (concat_<top>.v)
#   rtl.rpt        Catapult RTL report (<top>.rpt)
#   cycle.rpt      Catapult cycle report (cyc<top>.rpt)
# The only change made while copying: the value of the "Generated by:" header
# line (user@host of the run) is replaced with "<redacted>". Originals stay in
# hls/l0/run/<top>/ (not committed).
#
# Clock periods (one per library, used for every block and configuration):
#   fpga 40 ns, asic 6 ns. They are the smallest round values at which the
#   slowest block (mod_mul_shiftadd) still schedules at latency 1 (p1) with
#   Catapult's own delay model; at fpga 35 ns / asic 5 ns p1 fails (SCHD-20).
# Override with CLK_FPGA / CLK_ASIC.
set -u -o pipefail

TCL_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
HLS_DIR=$(cd "$TCL_DIR/.." && pwd)
BLK_RE=${1:-.}
LIB_RE=${2:-.}
CFG_RE=${3:-.}
CLK_FPGA=${CLK_FPGA:-40.0}
CLK_ASIC=${CLK_ASIC:-6.0}

BLOCKS="mod_red_barrett mod_red_mont12 mod_red_shiftadd mod_red_k2red
        mod_mul_barrett mod_mul_mont12 mod_mul_shiftadd mod_mul_k2red"
LIBS="fpga asic"
CFGS="c0 p1 p2"

collect() {
  local top=$1
  local sol=$HLS_DIR/run/$top/$top/$top.v1
  local out=$HLS_DIR/out/$top
  rm -rf "$out"
  mkdir -p "$out"
  local src dst
  for pair in "concat_$top.v:concat_rtl.v" "$top.rpt:rtl.rpt" "cyc$top.rpt:cycle.rpt"; do
    src=$sol/${pair%%:*}
    dst=$out/${pair##*:}
    [[ -f $src ]] || { echo "$top: missing $src"; return 1; }
    sed -E 's/^(\/\/|--)( +Generated by: +).*$/\1\2<redacted>/' "$src" >"$dst"
  done
}

n_fail=0
t_all=$SECONDS
for b in $BLOCKS; do
  [[ $b =~ $BLK_RE ]] || continue
  for l in $LIBS; do
    [[ $l =~ $LIB_RE ]] || continue
    clk=$CLK_FPGA
    [[ $l == asic ]] && clk=$CLK_ASIC
    for c in $CFGS; do
      [[ $c =~ $CFG_RE ]] || continue
      top=${b}_${l}_${c}
      if "$TCL_DIR/run_cfg.sh" "$b" "$l" "$c" "$clk" && collect "$top"; then
        :
      else
        n_fail=$((n_fail + 1))
      fi
    done
  done
done
echo "### run_all: $n_fail configuration(s) failed, wall=$((SECONDS - t_all))s"
exit $((n_fail > 0))
